+        assert.ok(filterForm.includes(`<option selected>${filter}</option>`));
+        assert.match(filterForm, /onchange="this.form.requestSubmit\(\)"/);
+        for (const form of text.matchAll(/<form[^>]*method="post"[\s\S]*?<\/form>/g)) {
