          assert.ok(form[0].includes(`name="filter" value="${filter}"`));
          assert.ok(form[0].includes(`name="priorityFilter" value="${priority}"`));
        }
      }
    }
    assert.equal(await html('/'), summary);
    const selection = { filter: 'Open', priorityFilter: 'High' };
